void switch_to_LPScreen_cb(lv_timer_t * timer)
{
    lv_timer_del(timer);  // optional
    start_inactivity_timer();
}

void anim_cb(lv_anim_t * out_anim)
{
    bootup_done = true;
    // Animation is completed, load active screen
    lv_disp_load_scr(ui_Welcomescreen);
    // Create a timer to switch to LP screen after boot
    lv_timer_create(switch_to_LPScreen_cb, APP_BOOTUP_DELAY, NULL);
}

lv_anim_t * bootup_Animation(lv_obj_t * TargetObject, int delay)
{
    lv_anim_t * out_anim;
    ui_anim_user_data_t * PropertyAnimation_0_user_data = lv_malloc(sizeof(ui_anim_user_data_t));
    PropertyAnimation_0_user_data->target = TargetObject;
    PropertyAnimation_0_user_data->imgset = (lv_img_dsc_t **)ui_imgset_img_;
    PropertyAnimation_0_user_data->imgset_size = sizeof(ui_imgset_img_) / (sizeof(lv_image_dsc_t *));
    PropertyAnimation_0_user_data->val = -1;
    lv_anim_t PropertyAnimation_0;
    lv_anim_init(&PropertyAnimation_0);
    lv_anim_set_time(&PropertyAnimation_0, 2500);
    lv_anim_set_user_data(&PropertyAnimation_0, PropertyAnimation_0_user_data);
    lv_anim_set_custom_exec_cb(&PropertyAnimation_0, _ui_anim_callback_set_image_frame);
    lv_anim_set_values(&PropertyAnimation_0, 1, 49);
    lv_anim_set_path_cb(&PropertyAnimation_0, lv_anim_path_linear);
    lv_anim_set_delay(&PropertyAnimation_0, delay + 0);
    lv_anim_set_deleted_cb(&PropertyAnimation_0, _ui_anim_callback_free_user_data);
    lv_anim_set_playback_time(&PropertyAnimation_0, 2500);
    lv_anim_set_playback_delay(&PropertyAnimation_0, 0);
    lv_anim_set_repeat_count(&PropertyAnimation_0, 1);
    lv_anim_set_repeat_delay(&PropertyAnimation_0, 0);
    lv_anim_set_early_apply(&PropertyAnimation_0, false);
    lv_anim_set_get_value_cb(&PropertyAnimation_0, &_ui_anim_callback_get_image_frame);
    lv_anim_set_completed_cb (&PropertyAnimation_0,anim_cb);
    out_anim = lv_anim_start(&PropertyAnimation_0);

    return out_anim;
}
