///////////////////// SCREENS ////////////////////
void ui_event____initial_actions0(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_SCREEN_LOAD_START) {
        app_speaker_audio_lvl_ctrl(AUDIO_LVL_MED);
        app_speaker_play(AUDIO_BOOTUP);
        bootup_Animation(ui_BootAnimImg, 0);
    }
}


void ui_init(void)
{
    lv_disp_t * dispp = lv_display_get_default();
    lv_theme_t * theme = lv_theme_default_init(dispp,
                                               lv_palette_main(LV_PALETTE_BLUE),
                                               lv_palette_main(LV_PALETTE_RED),
                                               false,
                                               LV_FONT_DEFAULT);
    lv_disp_set_theme(dispp, theme);

    // Initialize all screens

    ui_BootScreen_screen_init();
    ui_ActiveScreen_screen_init();
    ui_LPScreen_screen_init();
    ui_SettingsScreen_screen_init();
    ui_FWUpdateScreen_screen_init();
    ui_Welcomescreen_screen_init();
    ui_InfoScreen_screen_init();
    ui____initial_actions0 = lv_obj_create(NULL);
    lv_obj_add_event_cb(ui____initial_actions0, ui_event____initial_actions0,
                        LV_EVENT_ALL, NULL);

    lv_disp_load_scr(ui____initial_actions0);
    lv_disp_load_scr(ui_BootScreen);

    tutorialTimer = lv_timer_create(switchDescMessagecb, 3000, NULL);   //timer to switch between tutorial description messages
}


void ui_destroy(void)
{
    ui_ActiveScreen_screen_destroy();
    ui_BootScreen_screen_destroy();
    ui_SettingsScreen_screen_destroy();
    ui_FWUpdateScreen_screen_destroy();
    ui_LPScreen_screen_destroy();
    ui_InfoScreen_screen_destroy();
    ui_Welcomescreen_screen_destroy();
}
